const pickRevs = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Pick Revisions", parameters: { mode: 'runOnceForEachItem', jsCode: "const job = $('Split Summary Jobs').item.json;\nconst revs = $json.revisions || [];\nconst since = new Date(job.lock_since || 0);\nlet before = null;\nfor (const r of revs) if (new Date(r.modifiedTime) <= since) before = r;\nconst after = revs[revs.length - 1];\nconst changed = !!(before && after && before.id !== after.id);\nconst link = r => (r && r.exportLinks && r.exportLinks['text/plain']) || '';\nreturn { json: Object.assign({}, job, { changed, unknown: !revs.length, beforeUrl: link(before), afterUrl: link(after) }) };" } }, output: [{}] });
