const expBefore = node({ type: 'n8n-nodes-base.httpRequest', version: 4.4, config: { name: "Export Before", onError: 'continueRegularOutput', parameters: { method: 'GET', url: expr("{{ $json.beforeUrl }}"), authentication: 'predefinedCredentialType', nodeCredentialType: 'googleDriveOAuth2Api', options: { response: { response: { responseFormat: 'text', outputPropertyName: 'text' } } } }, credentials: { googleDriveOAuth2Api: { id: 'DpqEqE8imN1qRA0Y', name: 'Google Drive account' } } }, output: [{}] });
const expAfter = node({ type: 'n8n-nodes-base.httpRequest', version: 4.4, config: { name: "Export After", onError: 'continueRegularOutput', parameters: { method: 'GET', url: expr("{{ $('Pick Revisions').item.json.afterUrl }}"), authentication: 'predefinedCredentialType', nodeCredentialType: 'googleDriveOAuth2Api', options: { response: { response: { responseFormat: 'text', outputPropertyName: 'text' } } } }, credentials: { googleDriveOAuth2Api: { id: 'DpqEqE8imN1qRA0Y', name: 'Google Drive account' } } }, output: [{}] });
const claudeReq = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Build Claude Request", parameters: { mode: 'runOnceForEachItem', jsCode: "const job = $('Pick Revisions').item.json;\nconst a = String($('Export Before').item.json.text || '').slice(0, 40000);\nconst b = String($json.text || '').slice(0, 40000);\nconst prompt = 'Порівняй дві редакції документа «' + job.title + '» і коротко опиши українською, що саме змінилось у новій редакції: 2–6 стислих пунктів (що додано, видалено, змінено; з номерами пунктів/розділів, якщо є). Без вступу і висновків. Якщо змін по суті немає — напиши одним реченням.' + (job.comment ? ' Коментар автора правок: ' + job.comment : '') + '\\n\\n=== ПОПЕРЕДНЯ РЕДАКЦІЯ ===\\n' + a + '\\n\\n=== НОВА РЕДАКЦІЯ ===\\n' + b;\nreturn { json: { body: { model: 'claude-haiku-5-5', max_tokens: 700, messages: [{ role: 'user', content: prompt }] } } };" } }, output: [{}] });
const claude = node({ type: 'n8n-nodes-base.httpRequest', version: 4.4, config: { name: "Claude Summary", onError: 'continueRegularOutput', parameters: { method: 'POST', url: "https://api.anthropic.com/v1/messages", authentication: 'predefinedCredentialType', nodeCredentialType: 'anthropicApi', sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr("{{ JSON.stringify($json.body) }}"), sendHeaders: true, specifyHeaders: 'keypair', headerParameters: { parameters: [{ name: 'anthropic-version', value: '2023-06-01' }] } }, credentials: { anthropicApi: { id: 'mi2MApD6RkMgJKFw', name: 'Anthropic account' } } }, output: [{}] });
const collect = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Collect Summary", parameters: { mode: 'runOnceForEachItem', jsCode: "const job = $('Pick Revisions').item.json;\nlet summary;\nif ($json.content && $json.content[0] && $json.content[0].text) summary = $json.content[0].text.trim();\nelse if (job.unknown) summary = 'Не вдалося отримати історію версій документа.';\nelse if (!job.changed) summary = 'Змін у тексті не виявлено.';\nelse summary = 'Не вдалося сформувати AI-резюме змін. Перегляньте історію версій у Google Docs.';\nreturn { json: Object.assign({}, job, { summary }) };" } }, output: [{}] });
const editEmails = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Edit Emails", parameters: { mode: 'runOnceForAllItems', jsCode: "const esc = s => String(s || '').replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\nconst out = [];\nfor (const it of $input.all()) {\n  const j = it.json;\n  const head = j.auto ? 'Сесію редагування ' + esc(j.editor_name) + ' завершено автоматично (минув час блокування).' : esc(j.editor_name) + ' завершив(ла) правки.';\n  const html = '<div style=\"font-family:Arial,sans-serif;max-width:560px;margin:0 auto;color:#1f2937\"><div style=\"font-size:13px;color:#6b7280;margin-bottom:12px\">Портал погодження документів</div><h2 style=\"font-size:19px;margin:0 0 14px\">Внесено правки: «' + esc(j.title) + '»</h2><p style=\"font-size:14px;line-height:1.55\">' + head + ' Усі погодження обнулено — потрібно погодити нову редакцію.</p>' + (j.comment ? '<p style=\"font-size:14px;line-height:1.55\"><b>Коментар автора:</b> ' + esc(j.comment) + '</p>' : '') + '<div style=\"background:#f3f4f6;border-radius:8px;padding:12px 16px;font-size:14px;line-height:1.55\"><b>AI-резюме змін:</b><br>' + esc(j.summary).replace(/\\n/g, '<br>') + '</div><p style=\"margin:22px 0\"><a href=\"' + j.link + '\" style=\"background:#2563eb;color:#fff;text-decoration:none;padding:11px 20px;border-radius:6px;font-size:14px;display:inline-block\">Відкрити в порталі</a></p></div>';\n  for (const to of (j.recipients || [])) out.push({ json: { to, subject: '«' + j.title + '»: внесено правки — погодьте нову редакцію', html } });\n}\nreturn out;" } }, output: [{}] });
const sendEdit = node({ type: 'n8n-nodes-base.gmail', version: 2.2, config: { name: "Send Edit Email", onError: 'continueRegularOutput', parameters: { resource: 'message', operation: 'send', sendTo: expr("{{ $json.to }}"), subject: expr("{{ $json.subject }}"), emailType: 'html', message: expr("{{ $json.html }}"), options: { appendAttribution: false, senderName: 'Портал погодження документів' } }, credentials: { gmailOAuth2: { id: 'j7cmSIUTytvxUOqw', name: 'Gmail account K' } } }, output: [{}] });
const editRows = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Edit Rows", parameters: { mode: 'runOnceForAllItems', jsCode: "const crypto = require('crypto');\nconst now = new Date().toISOString();\nconst notes = []; const logs = [];\nfor (const it of $input.all()) {\n  const j = it.json;\n  logs.push([now, j.doc_id, 'system', 'ai_summary', j.summary]);\n  for (const to of (j.recipients || [])) notes.push(['N' + crypto.randomBytes(6).toString('hex'), now, to, j.doc_id, j.editor_name + ' вніс(ла) правки — погодьте нову редакцію', '']);\n}\nreturn [{ json: { notes, logs } }];" } }, output: [{}] });
const appendLog = node({ type: 'n8n-nodes-base.httpRequest', version: 4.4, config: { name: "Append Log Rows", onError: 'continueRegularOutput', parameters: { method: 'POST', url: "https://sheets.googleapis.com/v4/spreadsheets/1Xh_HNOkT8ZZCZ1rumHTPLufcPPk36tsre1O0i-6Xwg0/values/log!A1:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS", authentication: 'predefinedCredentialType', nodeCredentialType: 'googleSheetsOAuth2Api', sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr("{{ JSON.stringify({ values: $json.logs }) }}") }, credentials: { googleSheetsOAuth2Api: { id: 'tgFIdgSMvJdM4qiQ', name: 'Google Sheets account K' } } }, output: [{}] });
const appendNotes = node({ type: 'n8n-nodes-base.httpRequest', version: 4.4, config: { name: "Append Notification Rows", onError: 'continueRegularOutput', parameters: { method: 'POST', url: "https://sheets.googleapis.com/v4/spreadsheets/1Xh_HNOkT8ZZCZ1rumHTPLufcPPk36tsre1O0i-6Xwg0/values/notifications!A1:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS", authentication: 'predefinedCredentialType', nodeCredentialType: 'googleSheetsOAuth2Api', sendBody: true, contentType: 'json', specifyBody: 'json', jsonBody: expr("{{ JSON.stringify({ values: $('Edit Rows').first().json.notes }) }}") }, credentials: { googleSheetsOAuth2Api: { id: 'tgFIdgSMvJdM4qiQ', name: 'Google Sheets account K' } } }, output: [{}] });
export default workflow('doc-approval-portal', 'Портал погодження документів — API')
  .add(apiHook).to(setApi).to(normalize)
  .add(ackHook).to(setAck).to(normalize)
  .add(tick).to(setTick).to(normalize)
  .add(daily).to(setDaily).to(normalize)
  .add(normalize).to(read).to(check).to(needUpload
     .onTrue(toFile.to(uploadWord).to(convert).to(delOrig).to(logic))
     .onFalse(logic))
  .add(logic).to(hasWrites.onTrue(write.to(fan)).onFalse(fan))
  .add(fan).to(isHttp.onTrue(respond))
  .add(fan).to(splitEmails).to(sendEmail)
  .add(fan).to(splitDrive).to(listPerms).to(planPerm).to(permSwitch
     .onCase(0, createPerm)
     .onCase(1, updatePerm)
     .onCase(2, deletePerm))
  .add(createPerm).onError(createPermNotify)
  .add(fan).to(splitPdf).to(exportPdf).to(uploadPdf).to(movePdf).to(savePdf).to(buildAck).to(sendPdf)
  .add(fan).to(splitSum).to(listRevs).to(pickRevs).to(changed
     .onTrue(expBefore.to(expAfter).to(claudeReq).to(claude).to(collect))
     .onFalse(collect))
  .add(collect).to(editEmails).to(sendEdit)
  .add(collect).to(editRows).to(appendLog).to(appendNotes);
